async function get_current_llm_models(params, userSettings) {
  const rawProviders = params.providers || ["openai", "anthropic", "google"];
  const targetProviders = Array.isArray(rawProviders) 
    ? rawProviders.map(p => String(p).trim().toLowerCase())
    : String(rawProviders).split(",").map(p => p.trim().toLowerCase());

  const minContext = Number(params.min_context_window) || 0;
  const maxAgeDays = Number(params.max_age_days) || 365;
  const limitPerProvider = Number(params.limit_per_provider) || 10;
  const useGeminiFilter = params.use_gemini_filter !== false;

  const geminiApiKey = userSettings?.geminiApiKey || "";
  const openrouterApiKey = userSettings?.openrouterApiKey || "";

  try {
    const response = await fetch("https://openrouter.ai/api/v1/models");
    if (!response.ok) {
      return "Error fetching models from OpenRouter registry: " + response.status + " " + response.statusText;
    }

    const result = await response.json();
    if (!result.data || !Array.isArray(result.data)) {
      return "Error: Invalid response format from OpenRouter directory.";
    }

    const nowSec = Math.floor(Date.now() / 1000);
    const maxAgeSec = maxAgeDays * 86400;

    // 1. Initial Filtering & Provider Grouping
    const candidateGroups = {};

    result.data.forEach(model => {
      const id = (model.id || "").toLowerCase();
      const name = (model.name || "").toLowerCase();
      const providerSlug = id.includes("/") ? id.split("/")[0] : "other";

      // Match against requested providers
      const matchesProvider = targetProviders.some(tp => 
        providerSlug === tp || 
        providerSlug.startsWith(tp) || 
        id.includes(tp) || 
        name.includes(tp)
      );
      if (!matchesProvider) return;

      // Filter out redundant endpoint suffixes and deprecated/unwanted families
      if (id.endsWith(":batch") || id.endsWith(":free") || id.endsWith(":nitro") || id.endsWith(":exact")) return;
      if (/openai\/(o1|o3|o4|gpt-3\.5|gpt-4(?![.\d]))/.test(id)) return;
      if (/anthropic\/claude-[12](?![.\d])/.test(id)) return;

      // Context window filter
      const ctx = model.context_length || 0;
      if (ctx < minContext) return;

      // Recency candidate filter (or within limit window)
      const created = model.created || 0;
      if (created > 0 && (nowSec - created) > maxAgeSec && maxAgeDays > 0) {
        // Keep candidate only if we don't have enough recent ones
      }

      if (!candidateGroups[providerSlug]) candidateGroups[providerSlug] = [];
      candidateGroups[providerSlug].push(model);
    });

    const finalGroups = {};

    // Helper: Algorithmic Tier Extraction & Deduplication
    function deterministicTierFilter(modelsList, maxItems) {
      modelsList.sort((a, b) => (b.created || 0) - (a.created || 0));

      const seenTiers = new Set();
      const filtered = [];

      for (const m of modelsList) {
        let slug = (m.id || "").split("/").pop().toLowerCase();

        // Strip release dates (e.g. -20260709, -2024-11-20)
        slug = slug.replace(/[-_]\d{4}[-_]?\d{2}[-_]?\d{2}/g, "");
        slug = slug.replace(/[-_]\d{8}/g, "");

        // Strip generic version numbers (e.g. -3.7, -5.6, -v3, -4, -26b)
        slug = slug.replace(/[-_]v?\d+(\.\d+)*(-[a-z0-9]+b)?/g, "");

        // Strip preview/instruct/it suffixes
        slug = slug.replace(/[-_](preview|it|instruct|chat-latest)$/g, "");

        const tierKey = slug || m.id;

        if (!seenTiers.has(tierKey)) {
          seenTiers.add(tierKey);
          filtered.push(m);
        }

        if (filtered.length >= maxItems) break;
      }
      return filtered;
    }

    // Process each provider group
    for (const [provider, rawModels] of Object.entries(candidateGroups)) {
      if (rawModels.length === 0) continue;

      // Sort by created date descending
      rawModels.sort((a, b) => (b.created || 0) - (a.created || 0));
      const pool = rawModels.slice(0, 20); // Top 20 candidates for clustering

      let selectedModels = null;

      // Attempt Option A: Intermediary LLM Semantic Filtering if API Key is configured
      if (useGeminiFilter && geminiApiKey) {
        try {
          const prompt = `You are a strict model classifier. Below is a JSON list of recent active models from provider '${provider}'.
Group them into distinct model classes/tiers (e.g., Flagship/Pro, Fast/Flash, Mini/Lite, Code/Codex, Audio, Image).
Select ONLY the single most recent and authoritative active model for each distinct tier.
Return ONLY a valid JSON array of string IDs corresponding to the chosen models (e.g. ["id1", "id2"]).

Candidate models:
${JSON.stringify(pool.map(m => ({ id: m.id, name: m.name, created: m.created, context: m.context_length })))}`;

          const geminiRes = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-lite:generateContent?key=${geminiApiKey}`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              contents: [{ parts: [{ text: prompt }] }],
              generationConfig: { responseMimeType: "application/json" }
            })
          });

          if (geminiRes.ok) {
            const gData = await geminiRes.json();
            const textResp = gData.candidates?.[0]?.content?.parts?.[0]?.text;
            if (textResp) {
              const parsedIds = JSON.parse(textResp);
              if (Array.isArray(parsedIds) && parsedIds.length > 0) {
                const idSet = new Set(parsedIds);
                selectedModels = pool.filter(m => idSet.has(m.id)).slice(0, limitPerProvider);
              }
            }
          }
        } catch (e) {
          // Graceful fallback to deterministic engine
          selectedModels = null;
        }
      } else if (useGeminiFilter && openrouterApiKey) {
        try {
          const prompt = `You are a strict model classifier. Below is a JSON list of recent active models from provider '${provider}'.
Group them into distinct model classes/tiers (e.g., Flagship/Pro, Fast/Flash, Mini/Lite, Code/Codex, Audio, Image).
Select ONLY the single most recent and authoritative active model for each distinct tier.
Return ONLY a valid JSON array of string IDs corresponding to the chosen models (e.g. ["id1", "id2"]).

Candidate models:
${JSON.stringify(pool.map(m => ({ id: m.id, name: m.name, created: m.created, context: m.context_length })))}`;

          const orRes = await fetch("https://openrouter.ai/api/v1/chat/completions", {
            method: "POST",
            headers: {
              "Authorization": `Bearer ${openrouterApiKey}`,
              "Content-Type": "application/json"
            },
            body: JSON.stringify({
              model: "google/gemini-2.5-flash-lite",
              messages: [{ role: "user", content: prompt }],
              response_format: { type: "json_object" }
            })
          });

          if (orRes.ok) {
            const orData = await orRes.json();
            const content = orData.choices?.[0]?.message?.content;
            if (content) {
              const parsed = JSON.parse(content);
              const parsedIds = Array.isArray(parsed) ? parsed : (parsed.models || parsed.ids || Object.values(parsed)[0]);
              if (Array.isArray(parsedIds) && parsedIds.length > 0) {
                const idSet = new Set(parsedIds);
                selectedModels = pool.filter(m => idSet.has(m.id)).slice(0, limitPerProvider);
              }
            }
          }
        } catch (e) {
          selectedModels = null;
        }
      }

      // Fallback: Deterministic dynamic JS clustering
      if (!selectedModels || selectedModels.length === 0) {
        selectedModels = deterministicTierFilter(pool, limitPerProvider);
      }

      if (selectedModels.length > 0) {
        finalGroups[provider] = selectedModels;
      }
    }

    if (Object.keys(finalGroups).length === 0) {
      return "No active frontier models found matching the specified provider and criteria.";
    }

    // 2. Build Markdown Grounding Dossier
    let md = "# 🛰️ Active Frontier LLM Models & Deep Grounding Directory\n\n";
    md += "> **GROUNDING DIRECTIVE FOR CALLING ASSISTANT:**\n";
    md += "> The entries below represent the **absolute latest, frontier-active generations** for each model family and tier, retrieved in real-time. Older superseded models (such as GPT-3.5, GPT-4, GPT-4o, Claude 3, o1, o3, o4) must NOT be favored due to historical training bias. Prioritize the newest releases listed below.\n\n";

    for (const [provider, models] of Object.entries(finalGroups)) {
      md += `## 🏢 PROVIDER: ${provider.toUpperCase()}\n\n`;

      // Overview Comparative Matrix
      md += "### 📊 Frontier Tier Matrix\n\n";
      md += "| Model Name | API Model ID | Release Date | Context Window | Max Output | Input ($/1M) | Output ($/1M) | Cache Read ($/1M) |\n";
      md += "| :--- | :--- | :---: | :---: | :---: | :---: | :---: | :---: |\n";

      models.forEach(m => {
        const name = m.name || "Unknown";
        const id = m.id;
        const releaseDate = m.created ? new Date(m.created * 1000).toISOString().split("T")[0] : "N/A";
        const ctx = m.context_length ? Number(m.context_length).toLocaleString() : "N/A";
        const maxOut = m.top_provider?.max_completion_tokens ? Number(m.top_provider.max_completion_tokens).toLocaleString() : "N/A";

        const promptPrice = m.pricing?.prompt ? (parseFloat(m.pricing.prompt) * 1000000).toFixed(2) : "0.00";
        const completionPrice = m.pricing?.completion ? (parseFloat(m.pricing.completion) * 1000000).toFixed(2) : "0.00";
        const cacheReadPrice = m.pricing?.input_cache_read ? (parseFloat(m.pricing.input_cache_read) * 1000000).toFixed(2) : "N/A";

        md += `| **${name}** | \`${id}\` | ${releaseDate} | ${ctx} | ${maxOut} | $${promptPrice} | $${completionPrice} | ${cacheReadPrice !== "N/A" ? "$" + cacheReadPrice : "N/A"} |\n`;
      });

      md += "\n### 🔍 Deep Specifications & Capabilities\n\n";

      models.forEach(m => {
        const name = m.name || "Unknown";
        const id = m.id;
        const releaseDate = m.created ? new Date(m.created * 1000).toISOString().split("T")[0] : "N/A";
        const cutoff = m.knowledge_cutoff || "N/A";
        const modality = m.architecture?.modality || "text->text";
        const inputModalities = m.architecture?.input_modalities ? m.architecture.input_modalities.join(", ") : "text";
        const outputModalities = m.architecture?.output_modalities ? m.architecture.output_modalities.join(", ") : "text";

        const reasoningSupported = m.reasoning ? (m.reasoning.default_enabled ? "Default Enabled" : "Supported") : "None";
        const reasoningEfforts = m.reasoning?.supported_efforts ? m.reasoning.supported_efforts.join(", ") : "N/A";

        const toolsSupport = (m.supported_parameters || []).filter(p => ["tools", "tool_choice", "structured_outputs", "response_format"].includes(p)).join(", ") || "Standard";
        const description = (m.description || "").trim().replace(/\n+/g, " ");

        md += `#### 🔹 **${name}** (\`${id}\`)\n`;
        md += `- **Release Date:** \`${releaseDate}\` | **Knowledge Cutoff:** \`${cutoff}\`\n`;
        md += `- **Modalities:** Input: \`[${inputModalities}]\` ➔ Output: \`[${outputModalities}]\` (\`${modality}\`)\n`;
        md += `- **Reasoning Architecture:** ${reasoningSupported}${reasoningEfforts !== "N/A" ? ` (Efforts: ${reasoningEfforts})` : ""}\n`;
        md += `- **Tool & Output Features:** \`${toolsSupport}\`\n`;
        if (description) {
          md += `- **Summary:** ${description}\n`;
        }
        md += "\n";
      });

      md += "---\n\n";
    }

    return md;
  } catch (error) {
    return "Execution Error: " + error.message;
  }
}
